  // Calculate confidence via softmax
  const expScores = scores.map(s => Math.exp(s));
  const sumExp = expScores.reduce((a, b) => a + b, 0);
  const probs = expScores.map(e => e / sumExp);
  const confidence = probs[maxIdx];

  return {
    mode: LABELS[maxIdx],
    confidence,
    scores,
    probs,
  };
